export function isMobileDevice(ua: string | null) {
  if (!ua) return false;
  if (/android|webos|iphone|ipod|blackberry|iemobile|opera mini/i.test(ua)) {
    return true;
  } else {
    return false;
  }
}

export const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const pf = <T, U = any>() => {
  let resolve!: (value: T | PromiseLike<T>) => void;
  let reject!: (reason?: U) => void;
  const promise = new Promise<T>((_resolve, _reject) => {
    resolve = _resolve;
    reject = _reject;
  });
  return { promise, reject, resolve };
};

export const jump = (url: string, blank = true) => {
  const a = document.createElement('a');
  a.href = url;
  if (blank) {
    a.target = '_blank';
  }
  a.click();
};

export const download = (url: string, name?: string) => {
  const a = document.createElement('a');
  a.href = url;
  if (name) {
    a.download = name;
  }
  a.click();
};

export const getSuffix = (file: File | string) => {
  const name = typeof file === 'string' ? new URL(file).pathname : file.name;
  let suffix = name.split('.').pop()?.toLowerCase();
  if (file instanceof File) {
    suffix = suffix || file.type.split('/').pop();
  }
  return suffix;
};

export const readFileAsDataURL = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};
